const Palette &Get() { return Current(); }

void Set(Palette palette) { Current() = std::move(palette); }

utils::WrappedColor TypeColor(std::string_view type_name, bool is_custom) {
    return Get().TypeColor(type_name, is_custom);
}

utils::WrappedColor NodeAccent(std::string_view node_name,
                               std::string_view category) {
    return Get().NodeAccent(node_name, category);
}

